+/// One exact partial signature and its pure projected Jacobian. Neither the
+/// ray origin nor the UV/point enters this arithmetic. All residual-dependent
+/// arithmetic, singularity decisions and Newton state stay in the caller.
+/// Native production uses the original arithmetic without this storage.
+#[cfg(any(target_arch = "wasm32", test))]
+#[derive(Clone, Copy)]
+struct ProjectedJacobian {
+    ju: Vec3,
+    jv: Vec3,
+    a11: f64,
+    a12: f64,
+    a22: f64,
+    det: f64,
+}
+
+#[cfg(any(target_arch = "wasm32", test))]
+#[derive(Default)]
+struct JacobianCache {
+    entry: Option<([u64; 10], ProjectedJacobian)>,
+}
+
+#[cfg(any(target_arch = "wasm32", test))]
+impl JacobianCache {
+    fn key(su: Vec3, sv: Vec3, line: LineQuery) -> [u64; 10] {
+        [
+            su.x().to_bits(),
+            su.y().to_bits(),
+            su.z().to_bits(),
+            sv.x().to_bits(),
+            sv.y().to_bits(),
+            sv.z().to_bits(),
+            line.direction.x().to_bits(),
+            line.direction.y().to_bits(),
+            line.direction.z().to_bits(),
+            line.dir_len_sq.to_bits(),
+        ]
+    }
+
+    fn get(&self, su: Vec3, sv: Vec3, line: LineQuery) -> Option<ProjectedJacobian> {
+        self.entry
+            .and_then(|(key, value)| (key == Self::key(su, sv, line)).then_some(value))
+    }
+
+    fn record(&mut self, su: Vec3, sv: Vec3, line: LineQuery, value: ProjectedJacobian) {
+        let key = Self::key(su, sv, line);
+        // Nonfinite inputs/results keep the original arithmetic, including
+        // NaN behavior. Signed zero and subnormals retain their exact bits.
+        self.entry = (key.iter().all(|&bits| f64::from_bits(bits).is_finite())
+            && [
+                value.ju.x(),
+                value.ju.y(),
+                value.ju.z(),
+                value.jv.x(),
+                value.jv.y(),
+                value.jv.z(),
+                value.a11,
+                value.a12,
+                value.a22,
+                value.det,
+            ]
+            .iter()
+            .all(|x| x.is_finite()))
+        .then_some((key, value));
+    }
+}
