+    fn projected(su: Vec3, sv: Vec3, line: LineQuery) -> ProjectedJacobian {
+        let ju = su - line.direction * (su.dot(line.direction) / line.dir_len_sq);
+        let jv = sv - line.direction * (sv.dot(line.direction) / line.dir_len_sq);
+        let a11 = ju.dot(ju);
+        let a12 = ju.dot(jv);
+        let a22 = jv.dot(jv);
+        ProjectedJacobian {
+            ju,
+            jv,
+            a11,
+            a12,
+            a22,
+            det: a11.fma(a22, -(a12 * a12)),
+        }
+    }
