+    #[test]
+    fn jacobian_cache_keys_all_partial_direction_and_length_bits() {
+        let su = Vec3::new(0.3, 0.4, 0.5);
+        let sv = Vec3::new(-0.6, 0.7, 0.8);
+        let line = LineQuery {
+            origin: Point3::new(2.0, 3.0, 4.0),
+            direction: Vec3::new(0.1, -0.2, 1.3),
+            dir_len_sq: 1.74,
+        };
+        let mut cache = JacobianCache::default();
+        cache.record(su, sv, line, projected(su, sv, line));
+        assert!(cache.get(su, sv, line).is_some());
+        let key = JacobianCache::key(su, sv, line);
+        for index in 0..10 {
+            let mut changed = key;
+            changed[index] += 1;
+            let values = changed.map(f64::from_bits);
+            assert!(
+                cache
+                    .get(
+                        Vec3::new(values[0], values[1], values[2]),
+                        Vec3::new(values[3], values[4], values[5]),
+                        LineQuery {
+                            direction: Vec3::new(values[6], values[7], values[8]),
+                            dir_len_sq: values[9],
+                            ..line
+                        }
+                    )
+                    .is_none(),
+                "key component {index}"
+            );
+        }
+        // Completion's origin rebase changes residuals, but never this matrix.
+        let rebased = LineQuery {
+            origin: line.origin + line.direction * 2.0,
+            ..line
+        };
+        assert!(cache.get(su, sv, rebased).is_some());
+        let zero = Vec3::new(0.0, 0.4, 0.5);
+        cache.record(zero, sv, line, projected(zero, sv, line));
+        assert!(cache.get(Vec3::new(-0.0, 0.4, 0.5), sv, line).is_none());
+        // Exactly one retained signature: replacement cannot alias an old one.
+        assert!(cache.get(su, sv, line).is_none());
+        assert!(std::mem::size_of::<JacobianCache>() <= 176);
+    }
