+    #[test]
+    fn jacobian_cache_never_retains_nonfinite_inputs_or_results() {
+        let su = Vec3::new(0.3, 0.4, 0.5);
+        let sv = Vec3::new(-0.6, 0.7, 0.8);
+        let line = LineQuery {
+            origin: Point3::new(0.0, 0.0, 0.0),
+            direction: Vec3::new(1.0, 0.0, 0.0),
+            dir_len_sq: 1.0,
+        };
+        let key = JacobianCache::key(su, sv, line);
+        for index in 0..10 {
+            let mut changed = key;
+            changed[index] = f64::NAN.to_bits();
+            let values = changed.map(f64::from_bits);
+            let bad_su = Vec3::new(values[0], values[1], values[2]);
+            let bad_sv = Vec3::new(values[3], values[4], values[5]);
+            let bad_line = LineQuery {
+                direction: Vec3::new(values[6], values[7], values[8]),
+                dir_len_sq: values[9],
+                ..line
+            };
+            let mut cache = JacobianCache::default();
+            cache.record(
+                bad_su,
+                bad_sv,
+                bad_line,
+                projected(bad_su, bad_sv, bad_line),
+            );
+            assert!(cache.get(bad_su, bad_sv, bad_line).is_none());
+        }
+        for value in [
+            ProjectedJacobian {
+                det: f64::NAN,
+                ..projected(su, sv, line)
+            },
+            ProjectedJacobian {
+                a11: f64::INFINITY,
+                ..projected(su, sv, line)
+            },
+            projected(Vec3::new(1e308, 1e308, 1e308), sv, line),
+        ] {
+            let mut cache = JacobianCache::default();
+            cache.record(su, sv, line, value);
+            assert!(cache.get(su, sv, line).is_none());
+        }
+    }
