+    #[test]
+    #[allow(clippy::print_stderr)] // Deterministic work evidence, never a timing assertion.
+    fn one_entry_jacobian_work_on_general_surface_controls() {
+        let (mut calculations, mut hits, mut reference_calculations, mut roots) = (0, 0, 0, 0);
+        for surface in [
+            wavy_bicubic(),
+            rational_cylinder(),
+            rational_pole_patch(),
+            high_degree_patch(),
+        ] {
+            let grid = LineSurfaceSeedGrid::for_surface(&surface, 20);
+            for i in 1..=60_u32 {
+                let origin = Point3::new(
+                    8.0 * halton(i, 2) - 2.0,
+                    8.0 * halton(i, 3) - 2.0,
+                    6.0 * halton(i, 5) - 3.0,
+                );
+                let z = 2.0 * halton(i, 7) - 1.0;
+                let phi = std::f64::consts::TAU * halton(i, 11);
+                let r = (1.0 - z * z).max(0.0).sqrt();
+                let direction = Vec3::new(r * phi.cos(), r * phi.sin(), z);
+                let (actual, work) =
+                    intersection_jacobian_work(&surface, &grid, origin, direction, true);
+                let (expected, control) =
+                    intersection_jacobian_work(&surface, &grid, origin, direction, false);
+                assert_eq!(bits(&actual), bits(&expected), "ray {i}");
+                assert_eq!(
+                    work.jacobian_hits + work.jacobian_evaluations,
+                    control.jacobian_evaluations
+                );
+                calculations += work.jacobian_evaluations;
+                hits += work.jacobian_hits;
+                reference_calculations += control.jacobian_evaluations;
+                roots += actual.len();
+            }
+        }
+        eprintln!(
+            "one-entry general: 240 rays, {calculations}/{reference_calculations} Jacobian calculations; {hits} hits, {roots} roots"
+        );
+        assert!(roots > 20);
+    }
